		stageName: stage?.name || stage?.id || "Stage",
		stageId: stage?.id,
		duration: stageElapsedSeconds(task),
		status: "FAILED",
		content: failureReport,
		projectCwd: cwd,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
